function library(){const h=$('#blocks'),q=$('#search').value.toLowerCase();h.replaceChildren();for(const group of new Set(Object.values(catalog).map(t=>t.group))){const list=Object.entries(catalog).filter(([id,t])=>t.group===group&&(t.name+' '+t.description+' '+id).toLowerCase().includes(q));if(!list.length)continue;const details=E('details','','toolbox-group');details.open=!!q||S.groups.has(group);const summary=E('summary',group);summary.append(E('span',String(list.length),'count'));details.append(summary);details.ontoggle=()=>{if(!q)details.open?S.groups.add(group):S.groups.delete(group);};for(const [type,t]of list){const b=B('',()=>{S.preview=newNode(type);S.selected=null;S.edge=null;S.tab='config';canvas();inspector();layout();},'library-item');b.draggable=true;b.dataset.type=type;b.ondragstart=e=>e.dataTransfer.setData('application/th-node',type);const text=E('span');text.append(E('strong',t.name),E('small',t.description));b.append(blockIcon(type),text,E('span','◇','add-symbol'));details.append(b);}h.append(details);}$('#count').textContent=Object.keys(catalog).length;}

function add(type,x,y){if(!editable())return;if(S.procedureView&&['manager','leader','supervisor','reviewer','procedure'].includes(type))return toast('Add organizational positions from the organization overview.',true);checkpoint();const n=newNode(type,Math.round(x/10)*10,Math.round(y/10)*10);S.graph.nodes.push(n);if(S.procedureView){const procedure=S.graph.nodes.find(p=>p.id===S.procedureView);const ids=JSON.parse(procedure.config.nodeIds);ids.push(n.id);procedure.config.nodeIds=J(ids);if(isTaskBlock(n))S.graph.edges.push({id:uid(),source:procedure.id,sourcePort:'tasks',target:n.id,targetPort:'manager'});}S.selected=n.id;S.preview=null;S.edge=null;dirty();render();}
function issue(n){const connection=blockConnectionState(n,S.credentials,S.graph);if((connection.id||n.type==='social_publish'||agentTypes.includes(n.type))&&connection.state==='setup')return 'config';if(codingAgents[n.type]&&!S.credentials[codingAgents[n.type].provider])return 'config';if(catalog[n.type]?.service){const provider=catalog[n.type].service;if(!(provider==='google'?S.credentials.googleConnected:provider==='microsoft'?S.credentials.microsoftConnected:S.credentials[provider]))return 'config';}if(n.enabled===false)return 'disabled';if(n.type==='model'&&!S.credentials[n.config.provider||'gemini']||n.type==='perplexity'&&!S.credentials[searchProvider(n)]||n.type==='database'&&!S.credentials.postgres||n.type==='sheets'&&(!S.credentials.googleConnected||!n.config.spreadsheetId)||agentTypes.includes(n.type)&&!S.graph.edges.some(e=>e.target===n.id&&e.targetPort==='model'))return 'config';return 'idle';}
function nodeStatus(n){return (!S.runStale?S.run?.trace?.filter(t=>t.nodeId===n.id).at(-1)?.status:null)||issue(n);}
