async function previewWorkflow(){const allowed=['chat','output','function','set','stats','report','condition','note',...Object.keys(logicCatalog).filter(t=>!['dedupe','campaign_media','social_publish','trend_search'].includes(t))];if(S.graph.nodes.some(n=>n.enabled!==false&&!allowed.includes(n.type)))return toast('Connect and sign in to run server or cloud blocks. Use the Process JSON template for a free local preview.',true);let input={text:S.chat};try{if(/^\s*[\[{]/.test(S.chat))input=JSON.parse(S.chat);S.running=true;S.runStale=false;S.run={id:uid(),status:'running',trace:[]};render();S.previewController=new AbortController();const result=await executeWorkflow(S.graph,input,{signal:S.previewController.signal,executeFunction:(code,input)=>testFunction(code,input,{signal:S.previewController.signal}),onStep:async trace=>{S.run.trace=structuredClone(trace);canvas();consolePanel();}});S.run={...S.run,...result,status:'success'};toast('Local preview completed. This result is not saved to the server.');}catch(e){S.run={...S.run,status:'error',error:e.message};toast(e.message,true);}finally{S.previewController=null;S.running=false;render();}}

function starter(kind,{mode='factory'}={}){if(kind==='factory')return factoryTemplate({newNode,uid});if(blueprints.some(b=>b.id===kind))return mode==='flow'?buildBlueprint(kind,{newNode,uid}):buildFactoryBlueprint(kind,{newNode,uid});if(['agents','text'].includes(kind))return template(kind);const kinds={report:['chat','stats','report','output'],content:['chat','content_agent','output'],script:['chat','script_agent','output'],video:['chat','text_to_video','output']},types=kinds[kind]||kinds.report,nodes=types.map((type,i)=>newNode(type,80+i*310,160)),edges=nodes.slice(1).map((n,i)=>({id:uid(),source:nodes[i].id,sourcePort:'out',target:n.id,targetPort:'in'}));if(['content','script'].includes(kind)){const model=newNode('model',390,420);nodes.push(model);edges.push({id:uid(),source:model.id,sourcePort:'model',target:nodes[1].id,targetPort:'model'});}return {schemaVersion:1,nodes,edges};}


