function layout(){const root=$('.studio');root.classList.toggle('canvas-full',S.fullView);root.classList.toggle('inspector-hidden',!S.inspectorPinned&&!S.selected&&!S.edge&&!S.preview);for(const [key,value]of Object.entries(panelSizes))root.style.setProperty('--'+key+'-size',value+'px');const full=$('#tools button[title="Full view / restore panels"]');full?.setAttribute('aria-pressed',String(S.fullView));}
