function publisherSettings(body,n,update){let targets;try{targets=JSON.parse(n.config.targets);}catch{targets=[];}const names={facebook:['Facebook Page','srv_facebook_page'],youtube:['YouTube Channel','srv_youtube_videos'],threads:['Threads Account','srv_threads_profile'],tiktok:['TikTok Creator','srv_tiktok_account']};const list=E('div','','destination-list');for(const [platform,[label,type]]of Object.entries(names)){let target=targets.find(t=>t.platform===platform);if(!target){target={platform,accountId:'',enabled:false};targets.push(target);}const details=E('details','','destination-card'),summary=E('summary');summary.append(blockIcon(type),E('strong',label),E('small',target.enabled?'Enabled':'Not enabled'));details.append(summary);const panel=E('div','','destination-body'),change=(key,value)=>{target[key]=value;update('targets',JSON.stringify(targets,null,2));summary.querySelector('small').textContent=target.enabled?'Enabled':'Not enabled';};field(panel,'Enable this destination',target.enabled,v=>change('enabled',v),{type:'checkbox'});field(panel,'Exact account / channel ID',target.accountId,v=>change('accountId',v));if(platform==='youtube'){field(panel,'Video privacy',target.privacy||'private',v=>change('privacy',v),{options:[['private','Private'],['unlisted','Unlisted'],['public','Public']]});field(panel,'Content is made for kids',target.madeForKids===true,v=>change('madeForKids',v),{type:'checkbox'});}if(platform==='tiktok'){field(panel,'Creator-approved privacy',target.privacy||'SELF_ONLY',v=>change('privacy',v),{options:[['SELF_ONLY','Self only'],['PUBLIC_TO_EVERYONE','Public'],['MUTUAL_FOLLOW_FRIENDS','Mutual friends'],['FOLLOWER_OF_CREATOR','Followers']]});panel.append(E('p','The creator API must allow this privacy option. Verify the ai.th.io.vn domain / media URL prefix in your TikTok app.','muted'));}details.append(panel);list.append(details);}body.append(list);const advanced=E('details');advanced.append(E('summary','Advanced destinations JSON'));field(advanced,'Targets',n.config.targets,v=>update('targets',v),{type:'code',rows:12});body.append(advanced);}

function deliveryReview(id){dialog('Publishing receipts · owner review',async h=>{const data=await api('studio/media/'+id+'/delivery');h.append(E('p','Inspect the exact account/provider record before changing an uncertain delivery. Resuming Auto does not replay an uncertain write by itself.','muted'));if(!data.channels.length)h.append(E('p','No publishing attempts recorded.','muted'));for(const state of data.channels){const row=E('div','','list-card');row.append(E('strong',state.destination+' · '+state.status),E('p',state.reference||state.error||'No confirmed record ID','muted'));if(['uncertain','failed','intent'].includes(state.status)){let reference=state.reference||'';field(row,'Provider-confirmed record ID',reference,v=>reference=v);for(const [action,label]of [['confirm','Confirm published record'],['skip','Skip this destination'],['retry','Retry after confirming no post exists']])row.append(B(label,async()=>{if(!confirm('I inspected the provider. '+(action==='retry'?'No matching post exists; a later cycle may send a new request.':label)+'. Continue?'))return;try{await api('studio/media/'+id+'/delivery/review',{method:'POST',body:J({destination:state.destination,action,reference,acknowledge:true})});deliveryReview(id);toast('Review saved. Check all destinations before enabling Auto again.');}catch(e){toast(e.message,true);}},'secondary'));}h.append(row);}});}

function searchSettings(body,n,update){const provider=searchProvider(n);field(body,'Search provider',provider,v=>{update('provider',v);update('model',v==='openai'?'gpt-6.1-sol':'sonar');if(n.name==='Perplexity Search'||n.name==='OpenAI Web Search')n.name=v==='openai'?'OpenAI Web Search':'Perplexity Search';inspector();},{options:[['openai','OpenAI Web Search'],['perplexity','Perplexity Sonar']]});badge(body,provider);field(body,'Search model ID',n.config.model,v=>update('model',v));body.append(E('p',provider==='openai'?'Uses the saved OpenAI API key and Responses web_search. Web search/tool and model fees may apply. Search is required and actual citation URLs are returned.':'Uses a separate Perplexity Sonar API key. API access/credits are separate from chat subscriptions. A 403 requires checking key/project access, API billing or provider restrictions.','cost-note'));if(provider==='openai')modelDiscovery(body,n,update,'openai','responses');externalLink(body,'Search setup & pricing ↗',provider==='openai'?'https://developers.openai.com/api/docs/guides/tools-web-search':'https://docs.perplexity.ai/');}

function organizationConnections(host,n){
 if(!isTaskBlock(n))return;const offered=portsFor({...n,config:{...n.config,disabledPorts:[]}},catalog),disabled=new Set(n.config.disabledPorts||[]);host.append(E('h3','Connection channels'),E('p','Enable or remove supported channels. Task ⇄ connections carry approved assignments and returned reports. Flow stages data; it does not approve execution.','muted'));
 for(const [title,keys]of [['Input',['inputs.user','inputs.manager','inputs.in','inputs.observe','inputs.assessment']],['Controller',['inputs.model','inputs.memory','inputs.tool']],['Output',['outputs.user','outputs.tasks','outputs.report','outputs.assessment','outputs.tool',...Object.keys(offered.outputs).filter(k=>offered.outputs[k]==='flow').map(k=>'outputs.'+k)]]]){const group=E('details','','connection-channel-group');group.open=true;group.append(E('summary',title));for(const key of [...new Set(keys)]){const [side,name]=key.split('.');if(!offered[side][name])continue;const fixed=n.type==='manager'&&name==='user';field(group,name+' · '+offered[side][name],!disabled.has(key),enabled=>{if(!editable())return;const connected=S.graph.edges.filter(e=>side==='inputs'?e.target===n.id&&e.targetPort===name:e.source===n.id&&e.sourcePort===name);if(!enabled&&connected.length&&!confirm('Remove this channel and its '+connected.length+' connection(s)?')){inspector();return;}checkpoint();enabled?disabled.delete(key):disabled.add(key);n.config.disabledPorts=[...disabled];if(!enabled)S.graph.edges=S.graph.edges.filter(e=>!connected.includes(e));dirty();render();},{type:'checkbox',disabled:fixed});}host.append(group);}
 const parent=managementLinks(S.graph).find(l=>l.child===n.id);host.append(E('p','Direct manager: '+(parent?S.graph.nodes.find(x=>x.id===parent.parent)?.name:'User / not assigned'),'muted'));
}
function organizationConsole(){dialog('Factory organization',h=>{
 h.append(E('p','User → Manager → Team Leaders → staff and terminal operations. Management connections are bidirectional task/report channels. Supervisors are peers of Team Leaders and assess only Leader reports submitted to their shared Manager.','muted'));
 if(!isOrganization(S.graph)){h.append(B('Convert this workflow to a factory hierarchy',()=>{if(!editable())return;try{const converted=upgradeOrganization(S.graph),issues=validateGraph(converted);if(issues.length)throw Error(issues.join('\n'));checkpoint();S.graph=converted;S.entryNodeId=null;S.preview=null;S.selected=S.graph.nodes.find(n=>n.type==='manager')?.id;dirty();$('#modal').close();render();fit();toast('Hierarchy converted locally. Check and save to activate the new execution contract.');}catch(error){toast(error.message,true);}},'primary'),B('Wrap this Flow as an approved procedure',()=>{if(!editable())return;try{const converted=wrapFlowAsOrganization(S.graph,{newNode,uid},{title:S.title});const issues=validateGraph(converted);if(issues.length)throw Error(issues.join('\n'));checkpoint();S.graph=converted;S.active=false;S.procedureView=null;S.preview=null;S.selected=converted.nodes.find(n=>n.type==='manager').id;dirty();$('#modal').close();render();fit();toast('Existing Flow preserved inside a managed procedure. Check/save; review costs and scheduling before enabling Auto.');}catch(error){toast(error.message,true);}},'secondary'),B('Create a factory starter workflow',()=>{if(!discard())return;$('#modal').close();fresh('factory');},'secondary'));return;}
 const links=managementLinks(S.graph,{includeDisabled:true}),table=E('table','','organization-table'),header=E('tr');for(const title of ['Block','Role / operation','Direct manager','Direct reports'])header.append(E('th',title));table.append(header);for(const n of S.graph.nodes.filter(n=>isTaskBlock(n))){const row=E('tr'),parent=links.find(l=>l.child===n.id);row.append(E('td',n.name),E('td',agentTypes.includes(n.type)?getAgentRole(n).title:catalog[n.type].name),E('td',parent?S.graph.nodes.find(x=>x.id===parent.parent)?.name:'User'),E('td',String(links.filter(l=>l.parent===n.id).length)));table.append(row);}h.append(table);
 const settings=S.graph.settings?.organization||{},change=(key,value)=>{if(!editable())return;checkpoint();S.graph.settings={...S.graph.settings,organization:{...S.graph.settings?.organization,enabled:true,[key]:Number(value)}};dirty();};field(h,'Maximum model calls per run',settings.maxModelCalls??24,v=>change('maxModelCalls',v),{type:'number'});field(h,'Maximum Leader revisions',settings.maxLeaderRevisions??2,v=>change('maxLeaderRevisions',v),{type:'number'});field(h,'Parallel independent tasks',settings.parallelTasks??2,v=>change('parallelTasks',v),{type:'number'});field(h,'Execution deadline (seconds)',settings.timeoutSeconds??300,v=>change('timeoutSeconds',v),{type:'number'});h.append(E('p','Each manager analyzes its own objective, assigns tasks to direct reports, resolves their questions and chooses a result. Independent assignments can run concurrently; per-block ownership, required reviews, write approval and cost quotas remain enforced. Only the executive response is returned to the user.','muted'));
 const org=S.run?.output?.organization;if(org){h.append(E('h3','Task and approval ledger'));for(const r of org.reports||[])h.append(E('p',(S.graph.nodes.find(n=>n.id===r.blockId)?.name||r.blockId)+' · '+r.status+' · approved by '+(S.graph.nodes.find(n=>n.id===r.managerId)?.name||r.managerId)));h.append(E('h3','Independent assessments'));for(const a of org.assessments||[])h.append(E('p',(S.graph.nodes.find(n=>n.id===a.reviewerId)?.name||a.reviewerId)+' · '+a.phase+' · '+a.verdict+' · '+a.recommendation));}
 });}

function setupGuide(host,node){
 const guide=blockSetup(node,{catalog,graph:S.graph,credentials:S.credentials}),section=E('details','','block-setup-guide');section.append(E('summary','Setup checklist · '+(guide.issues.length?guide.issues.length+' item(s) need attention':'review settings')));section.append(E('p',guide.summary,'muted'),E('p',guide.cost,'cost-note'));
 if(guide.issues.length){const list=E('ul','','setup-issues');for(const issue of guide.issues)list.append(E('li',issue));section.append(list);}const steps=E('ol');for(const step of guide.setup)steps.append(E('li',step));section.append(steps);
 section.append(E('h3','Operation and reporting'));for(const text of guide.behavior)section.append(E('p',text,'muted'));section.append(E('p','Direct manager: '+guide.manager,'origin-label'));if(guide.scope)section.append(E('p','Required service scope: '+guide.scope,'origin-label'));
 const parameters=E('details');parameters.append(E('summary','Settings reference'));for(const p of guide.parameters){const row=E('div','','setting-reference');row.append(E('strong',p.key+(p.required?' · required':'')),E('small','Type: '+p.type),E('small',p.note),E('code','Default: '+(typeof p.default==='object'?J(p.default):String(p.default)).slice(0,240)));parameters.append(row);}section.append(parameters);
 const sample=E('details');sample.append(E('summary','Input example and channels'),E('pre',J(guide.example),'json-view'),E('p','Inputs: '+Object.entries(guide.channels.inputs).map(([k,v])=>k+' ('+v+')').join(', '),'muted'),E('p','Outputs: '+Object.entries(guide.channels.outputs).map(([k,v])=>k+' ('+v+')').join(', '),'muted'));section.append(sample);
 const errors=E('details');errors.append(E('summary','Troubleshooting'));for(const text of guide.failure)errors.append(E('p',text,'muted'));section.append(errors,E('p',guide.execution,'muted'));if(guide.docs)externalLink(section,'Official connection / API guide ↗',guide.docs);
 section.append(B('Fill missing defaults · preserve configured values',()=>{if(!editable())return;if(!S.preview)checkpoint();for(const [key,value]of Object.entries(catalog[node.type].defaults||{}))if(node.config[key]===undefined||node.config[key]===null)node.config[key]=structuredClone(value);if(!S.preview)dirty();render();toast('Only absent settings were filled. Existing settings and credentials were preserved.');},'secondary'));
 if(node.type==='procedure'){section.open=true;section.append(B('Open approved procedure',()=>openProcedure(node.id),'primary'),B('Edit procedure scope',()=>procedureScopeEditor(node),'secondary'));let ids=[];try{ids=JSON.parse(node.config.nodeIds);}catch{}section.append(E('p',ids.length+' checked Flow / controller blocks. Original event input and gate conditions are preserved.','muted'));}
 host.append(section);
}
function procedureScopeEditor(procedure){dialog('Approved procedure scope',h=>{h.append(E('p','Select the Flow, its one trigger, Output blocks and required controllers. Organizational managers and nested procedures cannot be included. Changing scope requires Check/save.','muted'));let chosen;try{chosen=new Set(JSON.parse(procedure.config.nodeIds));}catch{chosen=new Set();}const links=managementLinks(S.graph,{includeDisabled:true});for(const node of S.graph.nodes.filter(n=>!['manager','leader','supervisor','reviewer','procedure'].includes(n.type))){const parent=links.find(l=>l.child===node.id)?.parent,foreign=parent&&parent!==procedure.id&&!chosen.has(parent);field(h,node.name+' · '+catalog[node.type].name,chosen.has(node.id),enabled=>enabled?chosen.add(node.id):chosen.delete(node.id),{type:'checkbox',disabled:foreign});}h.append(B('Save procedure scope',()=>{if(!editable())return;checkpoint();procedure.config.nodeIds=J([...chosen]);S.graph.edges=S.graph.edges.filter(e=>!(e.source===procedure.id&&e.sourcePort==='tasks'&&!chosen.has(e.target)));for(const node of S.graph.nodes.filter(n=>chosen.has(n.id)&&isTaskBlock(n)))if(!managementLinks(S.graph,{includeDisabled:true}).some(l=>l.child===node.id)){node.config.disabledPorts=(node.config.disabledPorts||[]).filter(key=>key!=='inputs.manager');S.graph.edges.push({id:uid(),source:procedure.id,sourcePort:'tasks',target:node.id,targetPort:'manager'});}dirty();$('#modal').close();render();toast('Procedure scope updated locally. Check and save before executing.');},'primary'));});}
